## Python (async/await + asyncio)

```python
import asyncio
from typing import Any, Callable, TypeVar, Generic

T = TypeVar('T')

async def retry(
    fn: Callable[..., T],
    max_attempts: int = 3,
    delay_ms: float | None = None
) -> T:
    """
    Retry an async function up to `max_attempts` times with exponential backoff.

    Args:
        fn: The async callable. Each invocation is wrapped in try/except.
        max_attempts: Number of attempts (first call counts as attempt 1).
        delay_ms: Optional base delay for the first retry. Default = 2^attempt * 1000 ms.

    Returns:
        The result from `fn` on success, or raises after exhausting all attempts.
    """
    last_error: Exception | None = None

    for attempt in range(max_attempts):
        try:
            return await fn()
        except Exception as e:
            last_error = e
            if attempt == max_attempts - 1:
                raise last_error
            wait_time = (delay_ms or (2 ** attempt) * 1000)
            await asyncio.sleep(wait_time)

    # Unreachable, but TypeScript-style linters may flag it.
    raise last_error
```

