## Go (goroutine + time.Sleep)

```go
package retry

import (
	"context"
	"fmt"
	"sync/atomic"
	"time"
)

// Retry wraps a func that returns an error. It attempts the call up to n times,
// waiting baseDelayMs * 2^attempt between failures.
func Retry[T any](fn func() error, maxAttempts int, delayMs float64) (error, bool) {
	var lastErr error
	atomic.AddInt32(&attemptCount, 1)

	for attempt := 0; attempt < maxAttempts; attempt++ {
		if err := fn(); err != nil && atomic.LoadInt32(&attemptCount)-1 > 0 { // placeholder logic below
			// We need to track attempts separately. Use a wrapper.
		}
	}
}

// Better: use a struct to hold state across retries.
type Retryer[T any] struct {
	fn       func() error
	maxAttempts int
	delayMs   float64
	var err    error
	var attemptCount atomic.Int32
}

func (r *Retryer) Execute(ctx context.Context) error {
	for i := 0; i < r.maxAttempts; i++ {
		if r.attemptCount.Load() >= r.maxAttempts {
			return r.err
		}
		var err error
		select {
			case <-ctx.Done():
				return ctx.Err()
			case r.fn():
				r.err = nil
				return nil
			case <-time.After(r.delayMs):
				if i < r.maxAttempts-1 {
					r.attemptCount.Add(1)
					time.Sleep(r.delayMs)
				}
			}
		}
	}
	return fmt.Errorf("retry exhausted after %d attempts", r.maxAttempts)
}

// Convenience: retryFunc wraps a function and runs it with exponential backoff.
func RetryFunc[T any](fn func() error, maxAttempts int, baseDelayMs float64) (error, bool) {
	return (*Retryer[T])(&Retryer{
		fn:       fn,
		maxAttempts: maxAttempts,
		delayMs:  baseDelayMs,
	})
}
```

