## Rust (async + tokio)

```rust
use std::future::Future;
use std::pin::Pin;
use std::task::{Context, Poll};
use std::time::Duration;

/// Retry an async operation up to `max_attempts` times with exponential backoff.
///
/// # Arguments
/// * `fn` — The async function returning a Result<T, E>. Each invocation is wrapped in try/catch.
/// * `max_attempts` — Maximum number of attempts (including the first one).
/// * `base_delay_ms` — Optional base delay for the first retry; each subsequent delay = previous × 2 ms.
///
/// # Returns
/// Resolves with the result on success, or propagates after exhausting all attempts.
async fn retry<F, T, E>(
    mut f: F,
    max_attempts: usize,
    base_delay_ms: Option<f64>,
) -> Result<T, E>
where
    F: Future<Output = Result<T, E>> + Unpin,
{
    let mut last_error: Option<E> = None;

    for attempt in 0..max_attempts {
        match f().await {
            Ok(result) => return result,
            Err(e) if attempt < max_attempts - 1 => {
                last_error = Some(e);
                // Compute delay: base_delay_ms * (2 ^ attempt)
                let mut delay_usis: u64 = 0;
                match base_delay_ms {
                    Some(d) => { for _ in 0..attempt { d *= 2; } }
                    None => { for _ in 0..attempt { d += 1; } // fallback linear? No — use pow(2, attempt)*1000
                        let mut delay_usis: u64 = (2i64::from(d) * 1'000).max_value();
                        break; }
                }
                // Simpler: compute as base_delay_ms * 2^attempt in microseconds.
                // We'll just use a helper below:
                let delay = if let Some(bd) = base_delay_ms {
                    (bd as u64).pow(attempt + 1) * 1000
                } else {
                    (1u64 << attempt) * 1000
                };
                // Convert to Duration
                let wait = Duration::from_millis(delay);
                tokio::time::sleep(wait).await;
            }
        }
    }

    Err(last_error.unwrap_or_else(|| std::panic::AssertUnwindSafe(E))?)
}
```

> **Note on the Rust version above** — it uses `tokio` for async sleep. The core logic is shown; in production you'd import `tokio`. Let me clean that up properly:

