/**
 * Retries an async operation with exponential backoff.
 *
 * @param fn            Operation to run. Called once per attempt.
 * @param maxAttempts   Total attempts, including the first. Must be >= 1.
 * @param baseDelayMs   Delay before the first retry. Doubles each retry.
 * @param maxDelayMs    Cap on any single delay (default 30s).
 * @param shouldRetry   Optional predicate; return false to fail fast.
 * @returns             The value from `fn` on success.
 * @throws              The last error once attempts are exhausted.
 */
export async function retry<T>(
  fn: () => Promise<T>,
  maxAttempts = 3,
  baseDelayMs = 100,
  maxDelayMs = 30_000,
  shouldRetry: (err: unknown) => boolean = () => true,
): Promise<T> {
  if (maxAttempts < 1) throw new RangeError("maxAttempts must be >= 1");

  let lastError: unknown;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      const isLast = attempt === maxAttempts - 1;
      if (isLast || !shouldRetry(err)) break;

      const delay = Math.min(baseDelayMs * 2 ** attempt, maxDelayMs);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError;
}
