"""Retry an async operation with exponential backoff."""

from __future__ import annotations

import asyncio
import random
from typing import Awaitable, Callable, Optional, TypeVar

T = TypeVar("T")


class RetryError(Exception):
    """Raised when every attempt failed. Carries the last underlying error."""

    def __init__(self, attempts: int, last_error: BaseException) -> None:
        super().__init__(f"retry failed after {attempts} attempt(s): {last_error!r}")
        self.attempts = attempts
        self.last_error = last_error


async def retry(
    fn: Callable[[], Awaitable[T]],
    max_attempts: int = 3,
    base_delay: float = 0.1,
    max_delay: float = 30.0,
    factor: float = 2.0,
    jitter: float = 0.0,
    retry_on: Optional[Callable[[BaseException], bool]] = None,
) -> T:
    """Call ``fn`` until it succeeds, backing off exponentially between attempts.

    Args:
        fn: Zero-argument callable returning an awaitable.
        max_attempts: Total attempts including the first (must be >= 1).
        base_delay: Seconds to wait before the first retry.
        max_delay: Upper bound for a single sleep, in seconds.
        factor: Multiplier applied to the delay after each failure.
        jitter: Fraction of the delay to randomise (0.0 = none, 0.5 = +/-50%).
        retry_on: Predicate deciding whether an exception is retryable.
            Defaults to retrying every ``Exception``.

    Returns:
        The value returned by ``fn``.

    Raises:
        RetryError: If all attempts fail.
        ValueError: If ``max_attempts`` < 1.
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")

    should_retry = retry_on or (lambda exc: isinstance(exc, Exception))
    delay = base_delay
    last_error: Optional[BaseException] = None

    for attempt in range(1, max_attempts + 1):
        try:
            return await fn()
        except BaseException as exc:  # noqa: BLE001 - re-raised below
            if not should_retry(exc):
                raise
            last_error = exc
            if attempt == max_attempts:
                break
            sleep_for = min(delay, max_delay)
            if jitter:
                sleep_for *= 1 + random.uniform(-jitter, jitter)
            await asyncio.sleep(max(0.0, sleep_for))
            delay *= factor

    assert last_error is not None
    raise RetryError(max_attempts, last_error) from last_error
