// ReadLines returns all non-empty lines from the given path.
func ReadLines(filePath string) []string {
	var lines []string
	file, err := os.Open(filePath)
	if err != nil {
		return nil // or panic/handle error as needed
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if line != "" { // skip blank lines
			lines = append(lines, line)
		}
	}
	return lines
}

// StreamLines is a generator that yields lines one at a time.
