#
# Usage: ./read_file_lines.sh <filepath>

function read_file_lines() {
    local file="$1"
    # Use while IFS= read -r line; do ... done to process each line
    # For collecting all lines, we can use a temp file or pipe through xargs/awk.
    # Here is the simplest approach: print each line as it's read.

    if [[ ! -f "$file" ]]; then
        echo "Error: File '$file' not found." >&2
        return 1
    fi

    while IFS= read -r line || [[ -n "$line" ]]; do
        # Strip trailing newline character(s)
        line="${line%$'\n'}"
        printf '%s\n' "$line"
    done < "$file"
}

# Example usage:
#   ./read_file_lines.sh myfile.txt

case "${1:-}" in
    *.txt|*")
        read_file_lines "$1"
        ;;
    *)
        echo "Usage: $0 <filename>" >&2
        exit 1
        ;;
esac
