/**
 * Simple LRU cache.
 *
 * Uses a Map, which in JS preserves insertion order: the first key is the
 * least-recently-used. On every get/set we delete+reinsert the key to move it
 * to the "most recently used" end.
 *
 * get: O(1)   set: O(1)   space: O(capacity)
 */
export class LRUCache<K, V> {
  private readonly capacity: number;
  private readonly map = new Map<K, V>();

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError(`capacity must be a positive integer, got ${capacity}`);
    }
    this.capacity = capacity;
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) return undefined;
    const value = this.map.get(key) as V;
    // Refresh recency.
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }

  set(key: K, value: V): void {
    if (this.map.has(key)) {
      this.map.delete(key);
    } else if (this.map.size >= this.capacity) {
      // Evict the least-recently-used entry (first key in insertion order).
      const oldest = this.map.keys().next();
      if (!oldest.done) this.map.delete(oldest.value);
    }
    this.map.set(key, value);
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  get size(): number {
    return this.map.size;
  }

  /** Keys from least- to most-recently used. */
  keys(): K[] {
    return [...this.map.keys()];
  }
}

// --- demo ---
if (require.main === module) {
  const cache = new LRUCache<string, number>(2);
  cache.set("a", 1);
  cache.set("b", 2);
  console.log(cache.get("a")); // 1  (a is now most recent)
  cache.set("c", 3);           // evicts "b"
  console.log(cache.get("b")); // undefined
  console.log(cache.get("c")); // 3
  console.log(cache.keys());   // [ 'a', 'c' ]
}
