// Package lru implements a simple LRU cache.
//
// A doubly linked list holds entries in recency order (front = most recently
// used) and a map gives O(1) lookup of the list node.
//
// Get: O(1)   Set: O(1)   Space: O(capacity)
package lru

import (
	"container/list"
	"fmt"
)

type entry[K comparable, V any] struct {
	key   K
	value V
}

type LRUCache[K comparable, V any] struct {
	capacity int
	ll       *list.List // front = most recently used
	items    map[K]*list.Element
}

// New returns a cache holding at most capacity entries.
func New[K comparable, V any](capacity int) (*LRUCache[K, V], error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("capacity must be a positive integer, got %d", capacity)
	}
	return &LRUCache[K, V]{
		capacity: capacity,
		ll:       list.New(),
		items:    make(map[K]*list.Element, capacity),
	}, nil
}

// Get returns the value and whether it was present. A hit refreshes recency.
func (c *LRUCache[K, V]) Get(key K) (V, bool) {
	if el, ok := c.items[key]; ok {
		c.ll.MoveToFront(el)
		return el.Value.(*entry[K, V]).value, true
	}
	var zero V
	return zero, false
}

// Set inserts or updates a key, evicting the least-recently-used entry when full.
func (c *LRUCache[K, V]) Set(key K, value V) {
	if el, ok := c.items[key]; ok {
		el.Value.(*entry[K, V]).value = value
		c.ll.MoveToFront(el)
		return
	}
	if c.ll.Len() >= c.capacity {
		if back := c.ll.Back(); back != nil {
			c.ll.Remove(back)
			delete(c.items, back.Value.(*entry[K, V]).key)
		}
	}
	c.items[key] = c.ll.PushFront(&entry[K, V]{key: key, value: value})
}

// Len reports the number of cached entries.
func (c *LRUCache[K, V]) Len() int { return c.ll.Len() }

// Keys returns keys from least- to most-recently used.
func (c *LRUCache[K, V]) Keys() []K {
	keys := make([]K, 0, c.ll.Len())
	for el := c.ll.Back(); el != nil; el = el.Prev() {
		keys = append(keys, el.Value.(*entry[K, V]).key)
	}
	return keys
}
