/**
 * Flatten a deeply nested array into a single level.
 *
 * Iterative (explicit stack) rather than recursive, so a pathologically deep
 * input cannot blow the call stack. Order is preserved: depth-first, left to
 * right, which is the same order a recursive version produces.
 *
 * Time:  O(n) where n = total number of elements across all nesting levels.
 * Space: O(n) for the output, plus O(d) for the stack where d = max depth.
 */
export function flatten<T>(input: readonly unknown[]): T[] {
  const out: T[] = [];
  // Push in reverse so the stack pops elements in original left-to-right order.
  const stack: unknown[] = [...input].reverse();

  while (stack.length > 0) {
    const value = stack.pop();
    if (Array.isArray(value)) {
      for (let i = value.length - 1; i >= 0; i--) stack.push(value[i]);
    } else {
      out.push(value as T);
    }
  }
  return out;
}

// --- demo ---
if (require.main === module) {
  const nested = [1, [2, [3, [4, [5]], 6]], 7, [[[8]]], []];
  console.log(JSON.stringify(flatten<number>(nested)));
  // -> [1,2,3,4,5,6,7,8]

  // Deep case: 100k levels of nesting must not overflow the stack.
  let deep: unknown = 42;
  for (let i = 0; i < 100_000; i++) deep = [deep];
  console.log(JSON.stringify(flatten<number>([deep as unknown[]])));
  // -> [42]
