"""Flatten a deeply nested list into a single level.

Iterative with an explicit stack, so deep nesting cannot hit Python's
recursion limit (default 1000). Order is depth-first, left to right.

Time:  O(n) over all elements across every nesting level.
Space: O(n) output + O(d) stack, d = max depth.
"""
from typing import Any, Iterable, List, TypeVar

T = TypeVar("T")


def flatten(items: Iterable[Any]) -> List[T]:
    out: List[T] = []
    stack = list(reversed(list(items)))

    while stack:
        value = stack.pop()
        if isinstance(value, (list, tuple)):
            stack.extend(reversed(value))
        else:
            out.append(value)
    return out


if __name__ == "__main__":
    nested = [1, [2, [3, [4, [5]], 6]], 7, [[[8]]], []]
    print(flatten(nested))  # [1, 2, 3, 4, 5, 6, 7, 8]

    # Deep case: 100k levels must not raise RecursionError.
    deep: Any = 42
    for _ in range(100_000):
        deep = [deep]
    print(flatten([deep]))  # [42]
