package main

import "fmt"

// Flatten collapses arbitrarily nested []any into a single-level []any.
//
// Iterative with an explicit stack: Go grows goroutine stacks dynamically, but
// an explicit stack keeps memory predictable and avoids deep recursion anyway.
// Order is depth-first, left to right.
//
// Time:  O(n) over all elements across every nesting level.
// Space: O(n) output + O(d) stack, d = max depth.
func Flatten(input []any) []any {
	out := make([]any, 0, len(input))
	stack := make([]any, 0, len(input))

	// Push in reverse so pops come out in original order.
	for i := len(input) - 1; i >= 0; i-- {
		stack = append(stack, input[i])
	}

	for len(stack) > 0 {
		value := stack[len(stack)-1]
		stack = stack[:len(stack)-1]

		if nested, ok := value.([]any); ok {
			for i := len(nested) - 1; i >= 0; i-- {
				stack = append(stack, nested[i])
			}
			continue
		}
		out = append(out, value)
	}
	return out
}

func main() {
	nested := []any{1, []any{2, []any{3, []any{4, []any{5}}, 6}}, 7, []any{[]any{[]any{8}}}, []any{}}
	fmt.Println(Flatten(nested)) // [1 2 3 4 5 6 7 8]

	// Deep case: 100k levels of nesting.
	var deep any = 42
	for i := 0; i < 100_000; i++ {
		deep = []any{deep}
	}
	fmt.Println(Flatten([]any{deep})) // [42]
}
