//! Flatten a deeply nested array into a single level.
//!
//! Rust's type system has no "array of anything" type, so nesting is modelled
//! with an explicit enum. That is the idiomatic equivalent of `any[]` in TS.
//!
//! Iterative with an explicit stack: no recursion, so no stack overflow on
//! pathological input. Order is depth-first, left to right.
//!
//! Time:  O(n) over all elements across every nesting level.
//! Space: O(n) output + O(d) stack, d = max depth.

#[derive(Debug, Clone, PartialEq)]
pub enum Nested {
    Value(i64),
    List(Vec<Nested>),
}

pub fn flatten(input: &[Nested]) -> Vec<i64> {
    let mut out: Vec<i64> = Vec::new();
    // Stack of slices still to visit; reversed so we pop left-to-right.
    let mut stack: Vec<&[Nested]> = vec![input];

    while let Some(slice) = stack.pop() {
        // Walk the slice in order; push the remainder back for later.
        for (i, item) in slice.iter().enumerate() {
            match item {
                Nested::Value(v) => out.push(*v),
                Nested::List(children) => {
                    // Remaining siblings go back on the stack *after* the
                    // children, so children are processed first (DFS order).
                    if i + 1 < slice.len() {
                        stack.push(&slice[i + 1..]);
                    }
                    stack.push(children.as_slice());
                    break;
                }
            }
        }
    }
    out
}

fn main() {
    let nested = vec![
        Nested::Value(1),
        Nested::List(vec![
            Nested::Value(2),
            Nested::List(vec![
                Nested::Value(3),
                Nested::List(vec![Nested::Value(4), Nested::List(vec![Nested::Value(5)])]),
                Nested::Value(6),
            ]),
        ]),
        Nested::Value(7),
        Nested::List(vec![Nested::List(vec![Nested::List(vec![Nested::Value(8)])])]),
        Nested::List(vec![]),
    ];
    println!("{:?}", flatten(&nested)); // [1, 2, 3, 4, 5, 6, 7, 8]

    // Deep case: 100k levels of nesting.
    let mut deep = Nested::Value(42);
    for _ in 0..100_000 {
        deep = Nested::List(vec![deep]);
    }
    println!("{:?}", flatten(&[deep])); // [42]
}
