## 1. TypeScript

```typescript
// run-parallel.ts
export interface ParallelResult<T> {
  status: 'fulfilled' | 'rejected';
  value?: T;
  error?: Error;
}

/**
 * Runs an array of async functions in parallel using Promise.allSettled.
 * Returns a single result object summarizing the outcome of each promise:
 *   - If all promises are fulfilled → { status: 'allSucceeded', results: [...] }
 *   - Otherwise          →  { status: 'someRejected', results: [{status, value/error}] } 
 *
 * Errors from any promise are collected; the function never throws.
 */
export async function runParallelAsync<T>(
  promises: Promise<T>[],
): Promise<ParallelResult<T>> {
  const settled = await Promise.allSettled(promises);

  // Separate fulfilled and rejected
  const results: ParallelResult<T>[] = [];
  let allFulfilled = true;

  for (const s of settled) {
    if (s.status === 'fulfilled') {
      results.push({ status: 'fulfilled', value: s.value, error: undefined });
    } else {
      // Rejected — collect the reason
      const msg =
        s.reason instanceof Error ? s.reason.message : String(s.reason);
      allFulfilled = false;
      results.push({ status: 'rejected', value: undefined, error: { message: msg } });
    }
  }

  return {
    status: allFulfilled ? 'allSucceeded' : 'someRejected',
    results,
  };
}
```

**Usage example:**

```typescript
async function main() {
  const p1 = async () => await fetch('/api/one');
  const p2 = async () => throw new Error('boom'); // will be caught, not fail fast

  const result = await runParallelAsync([p1, p2]);
  console.log(result.status);   // 'someRejected'
  console.log(result.results[0]); // { status: 'fulfilled', value: ..., error: undefined }
  console.log(result.results[1]); // { status: 'rejected', value: undefined, error: { message: 'boom' } }
}
```

