    """
    Run each callable in parallel via asyncio.gather(return_exceptions=True).
    Returns a dict mapping index → {'status': 'fulfilled'|'rejected', 'value': ..., 'error': ...}.
    """
    results = await asyncio.gather(*promises, return_exceptions=True)

    outcomes: List[dict] = []
    for i, res in enumerate(results):
        if isinstance(res, Exception):
            outcomes.append({
                "index": i,
                "status": "rejected",
                "value": None,
                "error": f"{type(res).__name__}: {res}",
            })
        else:
            outcomes.append({
                "index": i,
                "status": "fulfilled",
                "value": res,
                "error": None,
            })

    all_ok = all(o["status"] == "fulfilled" for o in outcomes)
    return {
        "all_succeeded": all_ok,
        "results": outcomes,
    }
