## 3. Go (goroutines + channels)

```go
// run_parallel.go
package main

import (
	"context"
	"fmt"
	"sync"
)

// ParallelResult holds the outcome of a single operation.
type ParallelResult struct {
	Index   int
	Status  string // "fulfilled" | "rejected"
	Value   interface{} // result or nil when rejected
	Error   error        // non-nil only when Status == "rejected"
}

// runParallelAsync runs an array of func() error in parallel and returns a slice of ParallelResult.
func runParallelAsync(ctx context.Context, ops []func() error) ([]ParallelResult, int) {
	var results []ParallelResult
	var wg sync.WaitGroup

	for i, op := range ops {
		wg.Add(1)
		go func(i int, f func()) {
			defer wg.Done()
			result := f()
			if err != nil {
				results = append(results, ParallelResult{
					Index:   i,
					Status:  "rejected",
					Value:   nil,
					Error:   fmt.Errorf("op[%d] failed: %v", i, err),
				})
			} else {
				results = append(results, ParallelResult{
					Index:   i,
					Status:  "fulfilled",
					Value:   result,
					Error:   nil,
				})
			}
		}(i, ops[i])
	}

	wg.Wait()
	return results, len(results)
}

func main() {
	var p1, p2 func() error
	p1 = func() { return fmt.Errorf("op1 failed") }
	p2 = func() { return 123 }

	results, _ := runParallelAsync(context.Background(), []func() error{p1, p2})
	for _, r := range results {
		fmt.Printf("%d: %s (value=%v)\n", r.Index, r.Status, r.Value)
	}
}
```

**Usage example:**

```go
var res []ParallelResult
ops := []func() error{
    func() { return fmt.Errorf("first op failed") },
    func() { return "success" },
}

runParallelAsync(context.Background(), ops) // returns 2 ParallelResults, one rejected

for _, r := range res {
    if r.Status == "rejected" {
        fmt.Println(r.Error)
    } else {
        fmt.Printf("index=%d value=%v\n", r.Index, r.Value)
