## 2. Rust

Rust's standard library offers both `Mutex` (manual) and `AtomicUsize` (lock-free). Here's the classic Mutex version:

```rust
use std::sync::{Arc, Mutex};
use std::thread;

struct Counter {
    count: mut usize,
}

impl Counter {
    fn new() -> Arc<Mutex<Counter>> {
        let counter = Counter { count: 0 };
        Arc::new(Mutex::new(counter))
    }

    // Increment atomically under the mutex lock.
    fn increment(&self) {
        let mut guard = self.lock().unwrap();
        guard.count += 1;
        println!("Rust Counter incremented to {}", guard.count);
    }

    // Decrement atomically under the mutex lock.
    fn decrement(&self) {
        let mut guard = self.lock().unwrap();
        if guard.count > 0 {
            guard.count -= 1;
            println!("Rust Counter decreased to {}", guard.count);
        } else {
            println!("Warning: counter went negative");
        }
    }

    // Read-only access.
    fn get(&self) -> usize {
        let mut guard = self.lock().unwrap();
        guard.count
    }
}

fn main() {
    let counter = Counter::new();

    let handles: Vec<_> = (0..5).map(|i| {
        thread::spawn(move || {
            // Each goroutine gets its own Arc clone, but the Mutex is shared.
            drop(counter.lock().unwrap()); // just to show sharing
            counter.increment();
        })
    }).collect();

    for _ in 0..5 {
        let c = Counter { count: 0 };
        thread::spawn(move || {
            c.increment();
        });
    }

    println!("Final counter value: {}", counter.get());
}
```

**Key points:**
- `Arc<Mutex<T>>` allows shared ownership across threads.
- `lock().unwrap()` borrows the guard; you must release it before returning (hence the pattern above — in production, use a helper like `std::sync::RwLock` or return an iterator).
- For true concurrent reads without blocking writes, consider `Arc<RwLock<usize>>`.

