# semaphore.py

import threading


class Semaphore:
    """A simple counting semaphore limiting concurrent access to N threads."""

    def __init__(self, slots: int):
        self._slots = slots
        self._held = 0          # number of permits currently held by a thread

    def wait(self):
        """Block until one permit is available."""
        while self._held >= self._slots:
            # tiny yield to avoid tight CPU spin; replace with asyncio.sleep if async
            import time
            time.sleep(0.001)
        self._held += 1

    def release(self):
        """Return a permit that may be used by another thread."""
        if self._held > 0:
            self._held -= 1


# ---- Example usage ----------------------------------------------------
if __name__ == "__main__":
    limiter = Semaphore(3)   # allow up to 3 concurrent calls

    def worker():
        print("Worker started")
        limiter.wait()
        print("Worker done (acquired permit)")
        limiter.release()

    threads = [threading.Thread(target=worker) for _ in range(5)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
```

**Key points**

* `_held` tracks how many permits are currently held.  
* `wait()` loops until the count drops below `slots`.  
* `release()` decrements the counter when a thread finishes.

