// Semaphore limits concurrent execution to N permits.
type Semaphore struct {
	mu    sync.Mutex // protects _permits and wait/Release
	slots int        // total number of permits
	active int       // currently held permits (internal bookkeeping)
}

func NewSemaphore(slots int) *Semaphore {
	return &Semaphore{
		slots: slots,
	}
}

// Wait blocks until a permit becomes available.
func (s *Semaphore) Wait() {
	s.mu.Lock()
	for s.active >= s.slots {
		// busy-wait; in production you might use time.Sleep(10*time.Millisecond)
	}
	s.active++
	s.mu.Unlock()
}

// Release returns a permit to the pool.
func (s *Semaphore) Release() {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.active > 0 {
		s.active--
	}
}

func main() {
	limiter := NewSemaphore(3) // allow up to 3 concurrent calls

	var wg sync.WaitGroup
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			fmt.Println("Worker started")
			limiter.Wait()
			fmt.Println("Worker done (acquired permit)")
			limiter.Release()
        }())
		wg.Wait()
}
```

**Key points**

* `Wait()` loops while the internal `active` count is at or above `slots`.  
* `Release()` decrements `active` when a worker finishes, effectively freeing a slot for others.

