def binary_search(arr: list[int], target: int) -> int:
    """
    Return the index of `target` in a sorted list `arr`,
    or -1 if not found.
    """
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2          # integer division
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1


