## 5️⃣ Bash (POSIX shell)

> *Bash’s array handling is limited to space‑separated values. The script below works for small integer arrays and assumes the target is an integer.*

```bash
#!/usr/bin/env bash

# binary_search.sh <sorted_array_as_space_separated> <target>
# Example: ./binary_search.sh "10 20 30 40" 25

if [[ $# -ne 2 ]]; then
    echo "Usage: $0 'space-separated sorted array' target" >&2
    exit 1
fi

array=("$1")          # first argument = the array elements
target="$2"

low=0
high=${#array[@]}-1   # last index of the array (0‑based)

while true; do
    mid=$(( (low + high) / 2 ))
    if [[ $mid -lt 0 || $mid -ge ${#array[@]} ]]; then
        break   # out of bounds → not found
    fi

    val=${array[$mid]}
    if (( val == target )); then
        echo "$mid"
        exit 0
    elif (( val < target )); then
        low=$(( mid + 1 ))
    else
        high=$(( mid - 1 ))
    fi
done

echo "-1"   # not found
```

