Below are three self‑contained implementations of **Longest Common Subsequence (LCS)** for two input strings. Each follows the classic dynamic‑programming approach and returns one LCS string (any valid longest subsequence).

---

## 1️⃣ TypeScript (`lcs.ts`)

```ts
/**
 * Returns one Longest Common Subsequence of `a` and `b`.
 */
export function lcs(a: string, b: string): string {
  const m = a.length;
  const n = b.length;

  // dp[i][j] = length of LCS of a[0..i-1] and b[0..j-1]
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Backtrack to construct one LCS string
  const result: string[] = [];
  let i = m, j = n;
  while (i > 0 && j > 0) {
    if (a[i - 1] === b[j - 1]) {
      result.push(a[i - 1]);
      i--;
      j--;
    } else if (dp[i - 1][j] >= dp[i][j - 1]) {
      i--;
    } else {
      j--;
    }
  }
  return result.reverse().join('');
}
```

