package main

import (
	"fmt"
)

func lcs(a string, b string) string {
	m, n := len(a), len(b)
	// dp[i][j] = length of LCS of a[:i] and b[:j]
	dp := make([][]int, m+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}

	for i := 1; i <= m; i++ {
		for j := 1; j <= n; j++ {
			if a[i-1] == b[j-1] {
				dp[i][j] = dp[i-1][j-1] + 1
		 } else {
				dp[i][j] = max(dp[i-1][j], dp[i][j-1])
		 }
		}
	}

	// Backtrack to construct one LCS string
	var result []rune
	i, j := m, n
	for i > 0 && j > 0 {
		if a[i-1] == b[j-1] {
			result = append(result, rune(a[i-1]))
			i--
			j--
	 } else if dp[i-1][j] >= dp[i][j-1] {
			i--
	 } else {
			j--
	 }
	return string(runes(result)...)
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	fmt.Println(lcs("abcde", "ace")) // → ace
}
