package main

import "fmt"

// mergeSort returns a new slice containing the sorted elements of src.
func mergeSort(src []int) []int {
	if len(src) <= 1 {
		return src
	}

	mid := len(src) / 2
	left := mergeSort(src[:mid])
	right := mergeSort(src[mid:])

	return append(append([]int{}, left...), right...)
}

// merge merges two sorted slices into one sorted slice.
func merge(left, right []int) []int {
	result := make([]int, 0, len(left)+len(right))
	i, j := 0, 0
	for i < len(left) && j < len(right) {
		if left[i] <= right[j] {
			result = append(result, left[i])
			i++
		} else {
			result = append(result, right[j])
			j++
		}
	}
	result = append(result, left[i:]...)
	result = append(result, right[j:]...)
	return result
}

func main() {
	sorted := mergeSort([]int{3, 1, 4, 1, 5, 9})
	fmt.Println(sorted) // [1 1 3 4 5 9]
}
