// Simpler recursive implementation using a helper that returns a new slice.
fn merge_sort(arr: &[T]) -> Vec<T> {
    if arr.len() <= 1 {
        return arr.to_vec();
    }
    let mid = arr.len() / 2;
    let (left, right) = (
        std::split_at(mid).into_ordered_iter(0..mid),
        std::split_at(mid).into_ordered_iter(mid..)
    );
    // Merge the two sorted halves
    merge(&left, &right)
}

fn merge(left: &[T], right: &[T]) -> Vec<T> {
    let mut result = Vec::with_capacity(left.len() + right.len());
    let mut i = 0;
    let mut j = 0;

    while i < left.len() && j < right.len() {
        if left[i].cmp(&right[j]).ok::<Ordering>() == Some(Ordering::LeastOrEqual) {
            result.push(left[i]);
            i += 1;
        } else {
            result.push(right[j]);
            j += 1;
        }
    }
    // Append remaining elements
    result.extend_from_slice(&left[i..].to_vec());
    result.extend_from_slice(&right[j..].to_vec());
    result
}

