## 3. Go

```go
// Node represents a single character in the trie.
type Node struct {
    children map[rune]*Node // rune-based for Unicode support
    isEndOfWord bool
}

func NewTrie() *Trie {
    return &Trie{
        root: &Node{children: make(map[rune]*Node), isEndOfWord: false},
    }
}

// Insert a word into the trie.
func (t *Trie) Insert(word string) {
    node := t.root
    for _, ch := range []rune(word) {
        if _, ok := node.children[ch]; !ok {
            node.children[ch] = &Node{children: make(map[rune]*Node), isEndOfWord: false}
        }
        node = node.children[ch]
    }
    node.isEndOfWord = true
}

// Search for a word in the trie.
func (t *Trie) Search(word string) bool {
    node := t.root
    for _, ch := range []rune(word) {
        if child, ok := node.children[ch]; ok {
            node = child
        } else {
            return false
        }
    }
    return node.isEndOfWord
}
```

**Usage:**
