/**
 * Recursively finds all files with the given extension.
 *
 * @param rootPath   Directory or path to start from
 * @param extension Extension suffix, e.g. ".txt", "py"
 */
export function findFilesByExtension(
  rootPath: string | Promise<string>,
  extension: string,
  options?: { recursive?: boolean; includeDirectories?: boolean }
): Promise<Array<{ fullPath: string; ext: string }>> {
  const results: Array<{ fullPath: string; ext: string }> = [];

  function walk(currentDir: string, depth = 0) {
    if (!options?.recursive || currentDir === rootPath && !options.includeDirectories) return;
    
    // If we're at the starting directory and recursion is disabled
    const shouldProcessCurrent = (currentDir === rootPath && options.recursive !== true);
    
    for (const entry of fs.readdirSync(currentDir, { withFileTypes: true })) {
      const fullPath = path.join(currentDir, entry.name);
      
      if (entry.isDirectory()) {
        walk(fullPath, depth + 1);
      } else if (extension.toLowerCase() === entry.name.toLowerCase().slice(-4) && !options.includeDirectories) {
        results.push({ fullPath: fullPath, ext: extension });
      }
    }
  }

  // Handle Promise root path
  let currentDir = options.rootPath ? await fs.promises.readdir(rootPath)[0] : rootPath;
  
  if (fs.existsSync(currentDir)) {
    walk(currentDir);
  } else {
    console.error(`Root path does not exist: ${currentDir}`);
  }

  return results;
}
```

