import os
from typing import List, Tuple, Union


def find_files_by_extension(
    root_path: str | os.PathLike[str],
    extension: str,
    recursive: bool = True,
    include_directories: bool = False
) -> List[Tuple[str, str]]:
    """
    Recursively finds all files with the given extension.

    Args:
        root_path: Directory or path to start from.
        extension: File extension without dot (e.g., 'txt') or with dot ('.txt').
        recursive: Whether to descend into subdirectories. Default True.
        include_directories: If False, skip directories and only return files.

    Returns:
        A list of tuples: (full_path, ext)
    """
    results = []
    
    # Normalize extension
    if not extension.startswith('.'):
        extension = '.' + extension
    
    for dirpath, _, filenames in os.walk(root_path):
        if recursive and include_directories:
            pass  # os.walk already recurses
        
        for filename in filenames:
            if filename.endswith(extension) or (not recursive and not filename.endswith(extension)):
                full_path = os.path.join(dirpath, filename)
                results.append((full_path, extension))
    
    return results
