    fn walk(dir: &Path, results: &mut Vec<(PathBuf, String)>) {
        for entry in fs::read_dir(dir).unwrap() {
            let path = entry?.path();
            if let Some(entries) = entry? {
                // Check file
                if entries.file_type().is_file() && path.to_string_lossy().ends_with(&ext) {
                    results.push((PathBuf::from(path), ext));
                }
                // Recurse into directory
                if entries.is_dir() {
                    walk(&path, results);
                }
            }
        }
    }

    walk(root, &mut results);
    results
}
```

