## 5. Bash (using `find`)

```bash
#!/usr/bin/env bash
# find_files.sh — Recursively finds all files with a given extension.

usage() {
    echo "Usage: $0 <root_dir> <extension>"
    echo "Example: $0 /home/user/docs .txt"
}

if [ "$#" -ne 2 ]; then
    usage
    exit 1
fi

ROOT_DIR="$1"
EXTENSION="$2"

# Escape the extension for find (e.g., ".TXT" stays as-is)
ESCAPED_EXT="${EXTENSION%.*}.${EXTENSION##*.}"

if [ -z "$ESCAPED_EXT" ]; then
    # No dot in extension — treat whole string as literal
    ESCAPED_EXT="$EXTENSION"
else
    ESCAPED_EXT=".$EXTENSION"
fi

# find starts with -name "*.ext" but we want exact match on the suffix.
# Use -type f to only get files, and -print0 for safety.

find "$ROOT_DIR" -type f \( -name "*${ESCAPED_EXT}" \) 2>/dev/null
```

