## 2. Python — built-in `sqlite3`

```python
import sqlite3

def create_table():
    conn = sqlite3.connect('example.db')
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL
        )
    ''')
    conn.commit()
    return conn

def insert(name: str) -> None:
    conn = sqlite3.connect('example.db')
    cur = conn.cursor()
    cur.execute('INSERT INTO users (name) VALUES (?)', (name,))
    conn.commit()
    conn.close()

def query() -> list[tuple]:
    import sqlite3
    conn = sqlite3.connect('example.db')
    cur = conn.cursor()
    rows = cur.fetchall()
    for row in rows:
        print(row)
    conn.close()

# Demo
create_table()
insert('Alice')
query()
```

