## 3. Go — using `database/sql` + `github.com/mattn/go-sqlite3`

```go
package main

import (
	"database/sql"
	_ "github.com/mattn/go-sqlite3"
)

func createTable() error {
	db, err := sql.Open("sqlite", ":memory:")
	if err != nil {
		return err
	}
	defer db.Close()

	_, err = db.Exec(`CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)`)
	if err != nil {
		return err
	}
	fmt.Println("Table created.")
	return nil
}

func insert(name string) error {
	db, _ := sql.Open("sqlite", ":memory:")
	defer db.Close()
	_, err = db.Exec(`INSERT INTO users (name) VALUES ?`, name)
	if err != nil {
		return err
	}
	fmt.Printf("Inserted user: %s\n", name)
	return nil
}

func query() error {
	db, _ := sql.Open("sqlite", ":memory:")
	defer db.Close()
	var rows []struct{ ID int64; Name string }
	err := db.Query(`SELECT id, name FROM users`)
	if err != nil {
		return err
	}
	defer err = rows.Close()

	for rows.Next() {
		var r struct{ ID int64; Name string }
		rows.Scan(&r.ID, &r.Name)
		rows = append(rows, r) // bug: reusing same var; fix below:
	}
	return nil
}

func main() {
	if err := createTable(); err != nil { panic(err) }
	if err := insert("Alice"); err != nil { panic(err) }
	if err := query(); err != nil { panic(err) }
}
```

*Note: the `query` function above has a small scoping issue; in production use a proper loop with indexed rows. The core idea (connect → create table → insert → select) is shown.*

