### 2️⃣ Python (plain classes / dataclasses)

```python
# entity.py
from dataclasses import dataclass, field
from typing import Any, Dict

@dataclass
class Record:
    id: str
    data: Dict[str, Any] = field(default_factory=dict)
    version: int = 0   # optimistic‑lock field

    def get_snapshot(self) -> dict:
        return {
            "id": self.id,
            "data": self.data,
            "version": self.version,
        }

    def save(
        self,
        update_data: Dict[str, Any],
        expected_version: int | None = None
    ) -> None:
        snapshot = self.get_snapshot()
        if expected_version is not None and snapshot["version"] != expected_version:
            raise ConflictError(f"Conflict – record {snapshot['id']} version changed from {snapshot['version']} to {expected_version}")
        # Apply updates
        self.data.update(update_data)
        self.version += 1
```

**Usage**

```python
rec = Record(id="r-42", data={"name": "Alice"})
print(rec.get_snapshot())   # {'id': 'r-42', 'data': {...}, 'version': 0}

# Update only if version is still 0
try:
    rec.save({"name": "Bob"}, expected_version=0)
except ConflictError as e:
    print(e)                # Conflict – record r-42 version changed from 0 to ...
```

