### 3️⃣ Go (struct + method)

```go
// entity.go
package main

import (
	"errors"
	"fmt"
)

type Record struct {
	ID        string   `json:"id"`
	Data      map[string]interface{} `json:"data,omitempty"`
	Version   int       `json:"version"` // optimistic‑lock field
}

func (r *Record) GetSnapshot() map[string]interface{} {
	return map[string]interface{}{
		"id":        r.ID,
		"data":     r.Data,
		"version":  r.Version,
	}
}

// Save attempts the update only if `expectedVersion` matches the current one.
func (r *Record) Save(updateData map[string]interface{}, expectedVersion int) error {
	snapshot := r.GetSnapshot()
	if expectedVersion != nil && snapshot["version"] != expectedVersion {
		return fmt.Errorf("conflict: record %s version changed from %d to %d", r.ID, snapshot["version"], expectedVersion)
	}
	r.Data = updateData
	r.Version++
	return nil
}

// Example usage (in main.go):
func main() {
	rec := &Record{ID: "r-42", Data: map[string]interface{}{"name": "Alice"}, Version: 0}
	fmt.Println(rec.GetSnapshot()) // map with id, data, version

	if err := rec.Save(map[string]interface{}{"name": "Bob"}, 0); err != nil {
		fmt.Printf("Update failed: %v\n", err)
	} else {
		fmt.Println("Record updated")
	}
}
```

**Note:** In Go the `Version` field is part of the struct; you can also expose a helper like `SaveWithExpectedVersion(id string, data map[string]interface{}, expected int) error`.

