type MemoizedFunction<T, K extends string> = (
  ...args: Parameters<ReturnType<typeof fn>>,
) => ReturnType<fn>;

interface CacheEntry {
  value: T;
  expiresAt: number;
}

class MemoizationCache<K extends keyof any, V> {
  private cache: Map<keyof any, { value: V; expiresAt: number }>;
  
  constructor(initialValue?: V) {}
  
  get(key: K): V | undefined {
    const entry = this.cache.get(key);
    if (entry && Date.now() < entry.expiresAt) return entry.value;
    this.cache.delete(key);
    return undefined;
  }
  
  set(key: K, value: V, ttlMs?: number) {
    const expiresAt = key ? new Date(Date.now() + (ttlMs ?? 5_0000)) : null;
    this.cache.set(key, { value, expiresAt });
  }
}

// memoize
export function memoize<T extends keyof any>(
  fn: (...args: Parameters<ReturnType<typeof fn>>) => T,
): MemoizedFunction<T> {
  const cache = new MemoizationCache<K extends keyof typeof fn>(fn);
  
  return function memoized(...args: Parameters<ReturnType<typeof fn>>): T {
    const key = JSON.stringify(args); // or a custom key
    if (cache.get(key) !== undefined) {
      return cache.get(key).value;
    }
    const result = fn(...args);
    cache.set(key, { value: result, expiresAt: Date.now() + 5_0000 }); // default TTL 5s
    return result;
  };
}
