// ── Types ───────────────────────────────────────────────
type Memoized<T> = (...args: Parameters<ReturnType<typeof fn>>) => T;

interface CacheEntry {
  value: T;
  expiresAt: number; // ms from now
}

// Simple in-memory cache keyed by a JSON string of the args.
function memoize<T extends any>(
  fn: (...args: Parameters<ReturnType<typeof fn>>) => T,
  options?: { ttlMs?: number }
): Memoized<T> {
  const defaultTTL = options?.ttlMs ?? 5_000; // ms
  const cache = new Map<string, CacheEntry>();

  return function memoized(...args: Parameters<ReturnType<typeof fn>>): T {
    const key = JSON.stringify(args);
    let entry = cache.get(key);

    if (entry !== undefined && Date.now() < entry.expiresAt) {
      return entry.value;
    }

    // Compute the result on first miss
    const result = fn(...args);
    cache.set(key, { value: result, expiresAt: Date.now() + defaultTTL });

    return result;
  };
}

// Example usage:
const addMemoized = memoize((a: number, b: number) => a + b, { ttlMs: 10_000 });
console.log(addMemoized(2, 3)); // 5
setTimeout(() => console.log(addMemoized(2, 3)), 15_000); // still 5 (cached)
