def sliding_window_sum(arr: list[int], k: int) -> list[int]:
    """
    Return a list of sums for each contiguous sub‑array of length k in arr.

    Parameters:
        arr: list of integers
        k:   positive integer window size (K)

    Returns:
        A new list containing the sum of every consecutive group of k elements.
    """
    if k <= 0 or len(arr) < k:
        return []

    result = []
    # initialise first window
    window_sum = sum(arr[:k])
    result.append(window_sum)

    for i in range(k, len(arr)):
        window_sum += arr[i] - arr[i - k]
        result.append(window_sum)

    return result


