// slidingWindowSum returns the sums of each consecutive subarray of length k.
func slidingWindowSum(arr []int, k int) []int {
	if k <= 0 || len(arr) < k {
		return []int{}
	}

	result := make([]int, 0, len(arr)-k+1)
	windowSum := 0
	for i := 0; i < k; i++ {
		windowSum += arr[i]
	}
	result = append(result, windowSum)

	for i := k; i < len(arr); i++ {
		windowSum -= arr[i-k]
		windowSum += arr[i]
		result = append(result, windowSum)
	}

	return result
}

func main() {
	fmt.Println(slidingWindowSum([]int{1, 2, 3, 4, 5}, 3)) // [6 9 12]
}
