fn sliding_window_sum(arr: &[i64], k: usize) -> Vec<i64> {
    if k <= 0 || arr.len() < k {
        return vec![];
    }

    let mut result = Vec::with_capacity(arr.len() - k + 1);
    let window_sum: i64 = arr[..k].iter().sum();
