// bfs.ts
type Graph = {
  adj: Record<string, string[]>;
};

function bfs(graph: Graph<Keyof typeof graph>, start: Keyof typeof graph, target: Keyof typeof graph): string | null {
  const queue: [string, string][] = [[start, []]]; // [node, path-so-far]
  const visited = new Set<string>();

  while (queue.length > 0) {
    const [current, path] = queue.shift()!;
    if (visited.has(current)) continue;
    visited.add(current);

    if (current === target) return path;

    for (const neighbor of graph.adj[current] ?? []) {
      if (!visited.has(neighbor)) {
        queue.push([neighbor, [...path, neighbor]]);
      }
    }
  }

  return null; // no path found
}

// --- Example usage ---
const graph: Graph<Keyof typeof graph> = {
  A: ['B', 'C'],
  B: ['A', 'D', 'E'],
  C: ['A', 'F'],
  D: ['B'],
  E: ['B', 'F'],
  F: ['C', 'E']
