## 2. Python

```python
from collections import deque
from typing import Dict, List, Optional

def bfs(graph: Dict[str, List[str]], start: str, target: str) -> Optional[List[str]]:
    """
    Returns the shortest path as a list of nodes from start to target,
    or None if no path exists.
    graph: adjacency-list dict {node: [neighbors]}
    """
    if start == target:
        return [start]

    visited = set()
    queue = deque([(start, [start])])

    while queue:
        node, path = queue.popleft()

        if node in visited:
            continue
        visited.add(node)

        for neighbor in graph.get(node, []):
            if neighbor == target:
                return path + [neighbor]
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))

    return None


# --- Example usage ---
if __name__ == "__main__":
    graph = {
        'A': ['B', 'C'],
        'B': ['A', 'D', 'E'],
        'C': ['A', 'F'],
        'D': ['B'],
        'E': ['B', 'F'],
        'F': ['C', 'E']
    }

    print(bfs(graph, 'A', 'F'))  # → e.g. ['A', 'C', 'F'] or similar
```

