## 2️⃣ Python (3.10+)

```python
# topological_sort.py
from collections import defaultdict, deque
from typing import List, Tuple

def topological_sort(edges: List[Tuple[int, int]]) -> List[int]:
    """
    Return a list of node IDs in topological order.
    edges: list of (source, destination) tuples.

    Raises ValueError if the graph contains a cycle.
    """
    # adjacency list
    adj = defaultdict(list)
    indeg = defaultdict(int)

    for u, v in edges:
        adj[u].append(v)
        indeg[v] += 1

    # ensure every node appears in indeg (initialise missing nodes to 0)
    for u in set(adj.keys()) | set(indeg.keys()):
        if u not in indeg:
            indeg[u] = 0

    # queue with zero‑indegree nodes
    q = deque([node for node, deg in indeg.items() if deg == 0])

    order: List[int] = []
    while q:
        node = q.popleft()
        order.append(node)

        for neighbor in adj.get(node, []):
            indeg[neighbor] -= 1
            if indeg[neighbor] == 0:
                q.append(neighbor)

    # If we didn't process all nodes → cycle detected
    if len(order) != len(indeg):
        raise ValueError("Graph contains a cycle – not a DAG")
    return order


# ---- Example usage ----
if __name__ == "__main__":
    dag_edges = [
        (5, 2),
        (5, 0),
        (4, 0),
        (4, 1),
        (2, 3),
    ]
    print(topological_sort(dag_edges))   # e.g. [5, 4, 2, ...]
```

**Explanation**

* `defaultdict(list)` builds the adjacency list.
* Indegree counters are incremented for each edge’s head node.
* Nodes with zero indegree start in a FIFO queue (`deque`).
* Decrement neighbours’ indegrees; enqueue when they hit zero.
* After the loop, compare processed count to total distinct nodes – mismatch ⇒ cycle.

