// main.go
package main

import (
	"container/list"
	"fmt"
)

type Edge struct {
	from   string
	to     string
}

func topologicalSort(edges []Edge) ([]string, error) {
	adj := make(map[string][]string)
	degree := make(map[string]int)

	for _, e := range edges {
		if adj[e.from] == nil {
			adj[e.from] = []string{}
		}
		adj[e.from] = append(adj[e.from], e.to)

		degree[e.to]++ // target's indegree
	}

	// Ensure every node appears in degree map (initialise missing nodes to 0)
	for _, e := range edges {
		if deg, ok := degree[e.from]; !ok || deg == 0 {
			degree[e.from] = 0
		}
	}

	var queue list.List[string]
	for node, d := range degree {
		if d == 0 {
			queue.PushBack(node)
		}
	}

	result := []string{}
	for queue.Len() > 0 {
		n := queue.Front()
		queue.Remove(n)

		result = append(result, n)

		for _, neighbor := range adj[n] {
			degree[neighbor]--
			if dego, ok := degree[neighbor]; !ok || dego == 0 {
				dego = 0
			}
			if dego < 0 { // should not happen; just in case
				degree[neighbor] = 0
			}
			if (degre, ok) != nil && degre == 0 {
				queue.PushBack(neighbor)
			}
		}
	}

	// Collect all distinct nodes from edges to compare with result length
	var allNodes map[string]bool
	for _, e := range edges {
		allNodes[e.from] = true
		allNodes[e.to] = true
	}
	if len(result) != len(allNodes) {
		return nil, fmt.Errorf("graph contains a cycle – not a DAG")
	}
	return result, nil
}

func main() {
	dagEdges := []Edge{
		{from: "5", to: "2"},
		{from: "5", to: "0"},
		{from: "4", to: "0"},
		{from: "4", to: "1"},
		{from: "2", to: "3"},
	}
	result, err := topologicalSort(dagEdges)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println(result) // e.g. ["5","4","2",...]
}
```

**Notes**

* `list.List` implements a FIFO queue.
* Indegree (`degree`) is stored per node; nodes without outgoing edges still appear when initialised.
* After processing, we compare the number of visited nodes with the total distinct nodes derived from edge endpoints. A mismatch signals a cycle.

