function permute(str: string): string[] {
  const result: string[] = [];

  function backtrack(chars: string[], index: number, current: string = "") {
    if (index === chars.length) {
      result.push(current);
      return;
    }
    for (let i = 0; i < chars.length; i++) {
      // pick char at position i
      const nextChars = chars.slice(0, i).concat(chars.slice(i + 1));
      backtrack(nextChars, index + 1, current + chars[i]);
    }
  }

  backtrack(str.split(''), 0, '');
  return result;
}

