fn permute(s: &str) -> Vec<String> {
    let chars: Vec<char> = s.chars().collect();
    let mut result: Vec<String> = vec![];

    fn backtrack(chars: &[char], index: usize, current: String) {
        if index == chars.len() {
            result.push(current.clone());
            return;
        }
        for i in 0..chars.len() {
            // pick char at position i
            let mut next_chars = chars.iter().cloned();
            next_chars.remove(i);
            backtrack(&next_chars, index + 1, current.chars().collect::<String>())
        }
    }

    backtrack(&chars, 0, String::new());
    result
}

