// src/Queue/TraceableQueue.ts

export class ThreadSafeQueue<T> {
  private items: T[] = [];

  // Enqueue an item to the back of the queue.
  enqueue(item: T): void {
    this.items.push(item);
  }

  // Dequeue and return the front element, or null if empty.
  dequeue(): T | null {
    return this.items.shift() ?? null;
  }

