# queue.py

import threading


class ThreadSafeQueue:
    """Thread-safe FIFO in-memory message queue."""

    def __init__(self):
        self._queue = []
        self._lock = threading.Lock()

    def enqueue(self, item):
        with self._lock:
            self._queue.append(item)

    def dequeue(self):
        with self._lock:
            if self._queue:
                return self._queue.pop(0)  # FIFO
            return None

    def peek(self):
        with self._lock:
            if self._queue:
                return self._queue[0]
            return None
```

*Thread‑safety note:* `threading.Lock()` guarantees that only one coroutine/thread can modify the list at a time.*

