type ThreadSafeQueue struct {
	q *list.List
	m sync.Mutex
}

// NewThreadSafeQueue creates a new queue.
func NewThreadSafeQueue() *ThreadSafeQueue {
	return &ThreadSafeQueue{
		q: make(list.List),
	}
}

// Enqueue adds an item to the back of the queue.
func (t *ThreadSafeQueue) Enqueue(item interface{}) {
	t.m.Lock()
	defer t.m.Unlock()
	t.q.PushBack(item)
}

// Dequeue removes and returns the front element, or nil if empty.
func (t *ThreadSafeQueue) Dequeue() interface{} {
	t.m.Lock()
	defer t.m.Unlock()
	return <-t.q
}

// Peek returns the front element without removing it, or nil if empty.
func (t *ThreadSafeQueue) Peek() interface{} {
	t.m.Lock()
	defer t.m.Unlock()
	return <-t.q
}
```

*Thread‑safety note:* `sync.Mutex` protects concurrent access to the underlying list; `<-t.q` blocks until an item is removed, so callers must handle empty results safely.*

