## TypeScript  (Node.js)

```ts
type MinHeapItem = { value: number }; // you can extend for custom comparators

class MinHeap<T extends Keyof Number | string> {
  private heap: MinHeapItem[] = [];

  constructor(private keyFn?: (value: T) => number) {}

  push(value: T): void {
    const item = { value, ...this.keyFn?.(value) };
    this.heap.push(item);
    this._siftUp(this.heap.length - 1);
  }

  pop(): T | undefined {
    if (this.heap.length === 0) return undefined;
    const min = this.heap[0];
    const last = this.heap.pop();
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this._siftDown(0);
    }
    return min.value;
  }

  private _key(val: MinHeapItem): number {
    // default numeric comparison; override via keyFn
    const k = val.keyFn ? (val as any).k : Number(val.value);
    return k;
  }

  private _siftUp(idx: number): void {
    while (idx > 0) {
      const parentIdx = Math.floor((idx - 1) / 2);
      if (this._key(this.heap[idx]) < this._key(this.heap[parentIdx])) {
        [this.heap[idx], this.heap[parentIdx]] = [this.heap[parentIdx], this.heap[idx]];
        idx = parentIdx;
      } else break;
    }
  }

  private _siftDown(idx: number): void {
    const len = this.heap.length;
    while (true) {
      let smallest = idx;
      const left = 2 * idx + 1;
      const right = 2 * idx + 2;

      if (left < len && this._key(this.heap[left]) < this._key(this.heap[smallest])) {
        smallest = left;
      }
      if (right < len && this._key(this.heap[right]) < this._key(this.heap[smallest])) {
        smallest = right;
      }

      if (smallest === idx) break;
      [this.heap[idx], this.heap[smallest]] = [this.heap[smallest], this.heap[idx]];
      idx = smallest;
    }
  }

  size(): number { return this.heap.length; }
}
```

