class MinHeap:
    def __init__(self):
        self._data = []

    def push(self, value):
        # Insert and then heapify up
        self._data.append((value, None))   # placeholder key for ordering; we'll use the value itself as priority
        self._sift_up(len(self._data) - 1)

    def pop(self):
        if not self._data:
            return None
        min_item = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return min_item[0]

    def _sift_up(self, idx):
        while idx > 0:
            parent_idx = (idx - 1) // 2
            if self._compare(self._data[idx], self._data[parent_idx]):
                self._swap(idx, parent_idx)
                idx = parent_idx
            else:
                break

    def _sift_down(self, idx):
        size = len(self._data)
        while True:
            smallest = idx
            left = 2 * idx + 1
            right = 2 * idx + 2
            if left < size and self._compare(self._data[left], self._data[smallest]):
                smallest = left
            if right < size and self._compare(self._data[right], self._data[smallest]):
                smallest = right
            if smallest != idx:
                self._swap(idx, smallest)
                idx = smallest
            else:
                break

    def _compare(a, b):
        # a and b are (value, key) tuples; we compare by value only for min-heap
        return a[0] < b[0]

    def _swap(i, j):
        self._data[i], self._data[j] = self._data[j], self._data[i]
