## Go

```go
package heapmin

import "fmt"

// MinHeap implements a min-heap for values of type T.
type MinHeap[T any] struct {
    items []T // each item is the raw value; we compare directly (works for comparable types)
}

func NewMinHeap[T any](key func(T) int64) *MinHeap[T] {
    return &MinHeap[T]{items: make([]int, 0)}
}

// push inserts v into the heap.
func (h *MinHeap[T]) Push(v T) {
    h.items = append(h.items, v)
    // sift up
    for i := len(h.items) - 1; i > 0; i-- {
        parentIdx := (i - 1) / 2
        if h.items[i] < h.items[parentIdx] {
            h.items[i], h.items[parentIdx] = h.items[parentIdx], h.items[i]
            i = parentIdx
        } else break
    }
}

// pop removes and returns the smallest element.
func (h *MinHeap[T]) Pop() int64 {
    if len(h.items) == 0 {
        return -1 // or use a sentinel; here we signal empty by returning zero value of T? Use interface{}
    }

    minIdx := 0
    for i, v := range h.items {
        if i != minIdx && h.items[i] < h.items[minIdx] {
            minIdx = i
        }
    }
    // swap smallest to root and shrink
    if len(h.items) > 1 {
        h.items[0], h.items[minIdx] = h.items[minIdx], h.items[0]
        // sift down from new root
        for i := 0; i < len(h.items); i++ {
            left, right := 2*i+1, 2*i+2
            smallest := i
            if left < len(h.items) && h.items[left] < h.items[smallest] {
                smallest = left
            }
            if right < len(h.items) && h.items[right] < h.items[smallest] {
                smallest = right
            }
            if smallest != i {
                h.items[i], h.items[smallest] = h.items[smallest], h.items[i]
                i = smallest
            } else break
        }
    }
    // remove last element (pop from end)
    h.items = h.items[:len(h.items)-1]
    return h.items[0]
}
```

