```rust
use std::cmp::{Ordering, PartialOrd};
use std::collections::BinaryHeap;

// Wrap a value with the natural ordering for min-heap.
#[derive(Copy, Clone, Eq, PartialEq)]
struct MinHeapItem {
    value: i32,
}

impl Ord for MinHeapItem {
    fn cmp(&self, other: &MinHeapItem) -> Ordering {
        // Rust's BinaryHeap is a max‑heap by default; we invert to get min.
        self.value.cmp(&other.value)
    }
}
impl PartialOrd for MinHeapItem {
    fn partial_cmp(&self, other: &MinHeapItem) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

// A wrapper that turns the Ord impl into a max‑heap and we invert.
#[derive(Debug)]
pub struct MinHeap<T: PartialOrd> {
    data: Vec<T>,
}

impl<T: PartialOrd + Eq + Copy> MinHeap<T> {
    pub fn new() -> Self {
        MinHeap { data: Vec::new() }
    }

    // push
    pub fn push(&mut self, value: T) {
        self.data.push(value);
        let mut i = self.data.len() - 1;
        while i > 0 && self.data[i] < self.data[(i - 1) / 2] {
            std::memmove(self.data[i], self.data[(i - 1) / 2]);
            (i - 1) / 2 = i;
            i -= 1;
        }
    }

    // pop
    pub fn pop(&mut self) -> Option<T> {
        if self.data.is_empty() { return None; }
        let mut swap_idx = 0;
        for i in (0..self.data.len()).rev() {
            let min_idx = self.data[i].cmp(&self.data[swap_idx]);
            if min_idx == Ordering::Less {
                std::memmove(self.data[i], self.data[swap_idx]);
                self.data.swap(swap_idx, i);
                swap_idx += 1;
            } else break;
        }
        // remove last element (the one we swapped to root)
        let value = self.data.remove(0).cloned().unwrap();
        // after removal, re‑heapify the remaining elements
        for i in 0..self.data.len() {
            let mut left = 2 * i + 1;
            let mut right = 2 * i + 2;
            let mut smallest = i;
            if left < self.data.len() && self.data[left] < self.data[smallest] {
                smallest = left;
            }
            if right < self.data.len() && self.data[right] < self.data[smallest] {
                smallest = right;
            }
            if smallest != i {
                std::memmove(self.data[i], self.data[smallest]);
                self.data.swap(i, smallest);
                i = smallest;
            } else break;
        }
        Some(value)
    }
}
