def diff_objects(a: dict, b: dict) -> dict:
    """
    Return a dictionary with three keys:
      - 'added': list of keys present in b but not in a.
      - 'removed': list of keys present in a but not in b.
      - 'modified': list of dicts {key, oldValue, newValue} for keys that exist
                    in both and have different values.

    Missing keys are treated as absent (i.e., if key not in dict -> missing).
    """
    added = []
    removed = []
    modified = []

    # Keys only in b
    for key in b:
        if key not in a:
            added.append(key)
        elif a[key] != b[key]:
            modified.append({"key": key, "oldValue": a[key], "newValue": b[key]})

    # Keys only in a
    for key in a:
        if key not in b:
            removed.append(key)
        elif a[key] != b[key]:
            modified.append({"key": key, "oldValue": a[key], "newValue": b[key]})

    return {"added": added, "removed": removed, "modified": modified}
