// diffObjects returns a DiffResult for two JSON objects.
func diffObjects(a, b map[string]interface{}) *DiffResult {
	var added []string
	var removed []string
	var modified []DiffEntry

	// Keys only in b (added)
	for key := range b {
		if _, ok := a[key]; !ok {
			added = append(added, key)
		} else if a[key] != b[key] {
			modified = append(modified, DiffEntry{Key: key, OldVal: a[key], NewVal: b[key]})
		}
	}

	// Keys only in a (removed)
	for key := range a {
		if _, ok := b[key]; !ok {
			removed = append(removed, key)
		} else if a[key] != b[key] {
			modified = append(modified, DiffEntry{Key: key, OldVal: a[key], NewVal: b[key]})
		}
	}

	return &DiffResult{
		Added:     added,
		Removed:   removed,
		Modified:  modified,
	}
}
