enum State {
  IDLE = 'idle',
  RUNNING = 'running',
  ERROR = 'error'
}

class StateMachine {
  private current: State;
  // Map keyed by "fromState-event" → nextState
  private transitions: Record<string, [State]>;

  constructor(initial: keyof State) {
    this.current = initial as State;
    this.transitions = new Map();
  }

  /** Register a transition from `from` on event `event` to `to`. */
  addTransition(from: keyof State, event: string, to: State): void {
    const key = `${from}-${event}`;
    if (!this.transitions.has(key)) {
      this.transitions.set(key, [to as State]);
    }
  }

  /** Attempt a transition on the current state. Throws if no matching entry exists. */
  transition(event: string): State {
    const key = `${this.current}-${event}`;
    if (!this.transitions.has(key)) {
      throw new Error(
        `Invalid transition from state '${this.current}' on event '${event}'. No defined path for this combination.`
      );
    }
    return (this.transitions.get(key) as [State])[0];
  }

  /** Helper to inspect all outgoing transitions from the current state. */
  getOutgoingEvents(): string[] {
    const now = `${this.current}-*`;
    return Array.from(this.transitions.keys()).filter(k => k.startsWith(now)).map(k => k.split('-')[1]);
  }
}

