```typescript
// observer-pattern/src/typeScript.ts

type Event = string;

interface Observer {
  update(event: Event, data?: any): void;
}

class Subject {
  private listeners = new Map<Event, Set<Observer>>();

  subscribe(event: Event, listener: (event: Event, data?: any) => void): () => void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    const set = this.listeners.get(event)!;
    set.add(listener);
    return () => this.removeListener(listener);
  }

  unsubscribe(observer: Observer): void {
    for (const [event, evSet] of this.listeners.entries()) {
      if (evSet.has(observer)) {
        evSet.delete(observer);
        break;
      }
    }
  }

  emit(event: Event, data?: any): void {
    const set = this.listeners.get(event);
    if (set) {
      for (const listener of set) {
        try { listener(event, data); } catch (_) {}
      }
    }
  }
}

// Convenience wrapper that lets you subscribe by event name
class EventEmitter extends Subject {
  constructor() {
    super();
  }

  // Subscribe a one-shot handler to an event
  onEvent<T = any>(event: Event, handler: (e: Event, d?: T) => void): () => void {
    return this.subscribe(event, handler);
  }
}

// Example usage:
const subject = new EventEmitter();

subject.onEvent('message', (msg, payload) => console.log(`Received: ${msg}`, payload));

subject.emit('message', { type: 'hello' });
