# observer-pattern/src/python.py

from typing import Callable, Any, Dict


class Subject:
    """Maintains a map of events to sets of listeners."""

    def __init__(self):
        self._listeners: Dict[str, set] = {}

    def subscribe(self, event: str, listener: Callable[[str, Any], None]) -> Callable[[], None]:
        """
        Register `listener` for the given `event`.
        Returns a one-shot unsubscribe callable.
        """
        if event not in self._listeners:
            self._listeners[event] = set()
        self._listeners[event].add(listener)
        return lambda: self.remove_listener(listener)

    def unsubscribe(self, listener: Callable[[str, Any], None]) -> None:
        """Remove `listener` from all events it was subscribed to."""
        for event in list(self._listeners.keys()):
            if listener in self._listeners[event]:
                self._listeners[event].discard(listener)
                # If the set becomes empty, we could remove the key here

    def emit(self, event: str, data: Any = None) -> None:
        """Invoke all registered listeners for `event` with optional `data`."""
        if event in self._listeners:
            for listener in self._listeners[event]:
                try:
                    listener(event, data)
                except Exception as e:
                    pass  # silently ignore errors from listeners


# Convenience wrapper
class EventEmitter(Subject):
    """Subscribe by event name and provide one-shot handlers."""

    def on_event(self, event: str, handler: Callable[[str, Any], None]) -> Callable[[], None]:
        return self.subscribe(event, handler)


# Example usage:
if __name__ == "__main__":
    subject = EventEmitter()

    subject.on_event("message", lambda msg, payload: print(f"Received: {msg}", payload))

    subject.emit("message", {"type": "hello"})
