// observer-pattern/src/go/main.go

package main

import (
	"fmt"
)

// Observer defines what a listener must implement.
type Observer interface {
	Update(event string, data any)
}

// Subject maintains per-event lists of observers and emits events to them.
type Subject struct {
	mu    sync.Mutex
	events map[string][]Observer // event -> list of observer instances
}

func NewSubject() *Subject {
	return &Subject{
		events: make(map[string][]Observer),
	}
}

// Subscribe adds the given Observer to the event's slice and returns a one-shot unsubscribe.
func (s *Subject) Subscribe(event string, observer Observer) func() {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, exists := s.events[event]; !exists {
		s.events[event] = []Observer{observer}
	} else {
		s.events[event] = append(s.events[event], observer)
	}

	return func() {
		s.mu.Lock()
		defer s.mu.Unlock()

		for i, o := range s.events[event] {
			if o == observer { // direct comparison works for interface values
				s.events[event][i] = s.events[event][(i+1)%len(s.events[event])]
				break
			}
		}
	}
}

// Emit invokes all observers registered for the given event.
func (s *Subject) Emit(event string, data any) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if observers, ok := s.events[event]; ok && len(observers) > 0 {
		for _, o := range observers {
			o.Update(event, data)
		}
	}
}

func main() {
	subject := NewSubject()

	// Subscribe
	unsub1 := subject.Subscribe("message", func(e string, d any) { fmt.Println(`msg: ${e}`, d) })
	unsub2 := subject.Subscribe("data", func(e string, d any) { fmt.Println(`data: ${e}`, d) })

	// Emit
	subject.Emit("message", "hello")
	subject.Emit("data", 42)
}
