    this.thresholds = thresholds;
  }

  async check(): Promise<void> {
    const now = new Date();
    if (now.getTime() - this.lastCheckTime.getTime() < 60000) return; // debounce

    this.lastCheckTime = now;

    // CPU usage via process.cpuUsage()
    const cpu = process.cpuUsage ? process.cpuUsage() : null;
    let cpuPct: number;
    if (cpu !== undefined && typeof cpu === 'number') {
      cpuPct = (cpu / 100) * 100; // convert to percentage
    } else {
      // fallback: use top-level CPU from child processes via pstats or node's built-in
      const { performance} = require('perf_hooks');
      cpuPct = performance.getFractionalBurstyCPU();
    }
    if (cpuPct === undefined) {
      console.warn('[Monitor] Could not determine CPU usage.');
      return;
    }

    // Memory via Node's built-in memory info
    const memInfo = process.memoryUsage?.() || {};
    let usedGB: number;
    for (const [key, value] of Object.entries(memInfo)) {
      if (key === 'heapUsed') { usedGB = parseFloat(value / 1024**3); break; }
      if (key === 'rss' && key !== 'total') { usedGB = parseFloat((value / 1024**3).toFixed(2)); break; }
    }

    const memPct: number;
    // RSS is in bytes, convert to GB
    let totalMem = Object.keys(memInfo).length === 0 ? 1 : (memInfo['total'] || 0);
    if (totalMem > 0) {
      usedGB = parseFloat((memInfo['heapUsed' as any]?.value ?? memInfo['rss']) / (1024**3));
    } else {
      // fallback: use node's process.memoryUsage
      const { heapUsed, rssMemory } = require('os').usage();
      usedGB = ((heapUsed + rssMemory) / 1024**3).toFixed(2);
    }
    memPct = (usedGB / totalMem * 100).toFixed(1);

    console.log(`[Monitor] CPU: ${cpuPct}%, Memory: ${memPct} GB`);
  }

  alert(): void {
    const cpuAlert = this.thresholds.cpu <= cpuPct ? `⚠️ CPU usage (${cpuPct}%) exceeds threshold (${this.thresholds.cpu}%)` : '';
    const memAlert = this.thresholds.memory <= parseFloat(usedGB) ? `⚠️ Memory used (${parseFloat(usedGB)} GB) exceeds threshold (${this.thresholds.memory} GB)` : '';

    console.log(`[ALERT] ${cpuAlert}${memAlert}`);
  }
