// TwoPhaseCommit.ts
/**
 * Simple in‑memory simulation of a two‑phase commit between participants A and B.
 *
 * Phases:
 *   Phase 1 – Prepare: coordinator sends "prepare" to each participant; they reply with their decision (true = ready, false = abort).
 *   Phase 2 – Commit/Abort: if all participants have replied "ready", the coordinator tells them to commit or abort.
 */

type ParticipantResponse = boolean; // true → participant is prepared and will follow the chosen outcome
type Decision = 'commit' | 'abort';

interface Participant {
  id: string;
  ready: Promise<boolean>;   // resolves when the participant has responded in Phase 1
}

class Coordinator {
  private participants: Record<string, Participant> = {};

  constructor(participants: { [id: string]: Participant }) {
    this.participants = participants as Record<string, Participant>;
  }

  /** Send a prepare request to a participant and wait for its response */
  async sendPrepare(pid: string): Promise<boolean> {
    const p = this.participants[pid];
    if (!p) throw new Error(`Unknown participant ${pid}`);
    // In reality you would issue an RPC; here we just resolve after a short delay.
    return (await new Promise(resolve => setTimeout(() => p.ready!.then(resolve), 500))) as boolean;
  }

  /** Record the final decision for each participant */
