```python
"""
two_phase_commit.py

A minimal in‑memory simulation of the Two‑Phase Commit protocol for two participants A and B.
"""

import asyncio
from typing import Dict, Callable


class Participant:
    """Represents a single participant (e.g., database transaction coordinator)."""

    def __init__(self, pid: str):
        self.id = pid
        self.ready: bool = False  # will be set after Phase 1 response

    async def prepare(self) -> None:
        """
        Simulate sending the 'prepare' request and waiting for a reply.
        Returns True if the participant is ready to commit/abort, False otherwise.
        """
        print(f"[Participant {self.id}] Sending PREPARE …")
        # In reality you would await an RPC; here we just wait 0.5 s then mark as prepared.
        await asyncio.sleep(0.5)
        self.ready = True
        print(f"[Participant {self.id}] Prepared (ready=True)")

    async def commit(self, decision: str):
        """Record the final outcome for this participant."""
        if not self.ready:
            raise RuntimeError(f"Participant {self.id} did NOT prepare – aborting.")
        print(f"[Participant {self.id}] Committing with decision = '{decision}'")

    async def abort(self, decision: str):
        """Record the final outcome for this participant."""
        if self.ready:
            raise RuntimeError(f"Participant {self.id} prepared but we are aborting.")
        print(f"[Participant {self.id}] Aborting (no commit)")


class Coordinator:
    """Orchestrates Phase 1 and Phase 2 of the 2PC."""

    def __init__(self, participants: Dict[str, Participant]):
        self.participants = participants

    async def run(self):
        # ---------- Phase 1: Prepare ----------
        print("=== Phase 1: Prepare ===")
        phase1_results = {}
        for pid in list(self.participants.keys()):   # iterate over a copy
            p = self.participants[pid]
            result = await p.prepare()
            phase1_results[pid] = result
            print(f"  → {p.id} responded: ready={result}")

        all_ready = all(phase1_results.values())
        print(f"\nAfter Phase 1 – A ready={phase1_results.get('A', False)}, B ready={phase1_results.get('B', False)}")

        # ---------- Decision for Phase 2 ----------
        decision = 'commit' if all_ready else 'abort'
        print(f"All participants are prepared → proceeding to Phase 2 with decision: {decision}")
        await self._apply_decision(decision)

    async def _apply_decision(self, decision: str):
        """Send commit or abort messages to each participant."""
        for pid in ['A', 'B']:
            p = self.participants[pid]
            if decision == 'commit':
                await p.commit(decision)
            else:
                await p.abort(decision)


# -------------------------------------------------------------------
if __name__ == "__main__":
    # Instantiate participants
    participant_a = Participant('A')
    participant_b = Participant('B')

    coordinator = Coordinator({
        'A': participant_a,
        'B': participant_b,
    })

    asyncio.run(coordinator.run())
```

**What the Python code does**

| Step | Action (Python) |
|------|-----------------|
| **Phase 1 – Prepare** | For each participant (`'A'` and `'B'`), call `participant.prepare()`. Each method sleeps 0.5 s to simulate network latency, then sets `self.ready = True`. The results are collected in `phase1_results`. |
| **Decision** | If *both* entries are `True`, the coordinator decides `"commit"`; otherwise it picks `"abort"`. In this example we force A to be ready and B not (so the outcome will be an abort). |
| **Phase 2 – Commit/Abort** | `_apply_decision` calls either `participant.commit(decision)` or `participant.abort(decision)`. The commit method raises if a participant didn't prepare, and abort does not require preparation. |

