/**
 * Compute cosine similarity between two numeric vectors.
 *
 * @param a - first vector (array of numbers)
 * @param b - second vector (array of numbers, same length as `a`)
 * @returns value in [-1, 1]; 0 if either norm is zero
 */
function cosineSimilarity(a: number[], b: number[]): number {
  const dot = a.reduce((sum, v) => sum + v*b.forEach(v2 => { /* Oops – need correct indexing */ }), 0); // placeholder

  // Correct implementation:
  let dotProduct = 0;
  for (let i = 0; i < a.length; i++) {
    const ai = a[i];
    const bi = b[i];
    if (ai !== undefined && bi !== undefined) {
      dotProduct += ai * bi;
    }
  }

  const normA = Math.sqrt(a.reduce((s, v) => s + v * v, 0));
  const normB = Math.sqrt(b.reduce((s, v) => s + v * v, 0));

  if (normA === 0 || normB === 0) return 0;
  return dotProduct / (normA * normB);
