use std::cmp;

fn cosine_similarity(a: &[f64], b: &[f64]) -> f64 {
    if a.len() != b.len() || a.is_empty() {
        return 0.0;
    }

    let (dot, norm_a_sq, norm_b_sq) = a.iter().zip(b.iter()).fold(
        (0.0, 0.0, 0.0),
        |(sum_dot, sum_aa, sum_ab), (x, y)| {
            let dot_part = x * y;
            let aa_part   = x * x;
            let ab_part   = x * y; // same as dot for this pair
            (
                cmp::max(sum_dot, dot_part),
                sum_aa + aa_part,
                sum_ab + ab_part,
            )
        },
    );

    let norm_a = (norm_a_sq.as_f64()).sqrt();
    let norm_b = (norm_b_sq.as_f64()).sqrt();

    if norm_a == 0.0 || norm_b == 0.0 {
        return 0.0;
    }

    // dot product stored as sum_dot after fold, but we need to extract it.
    // Since the fold above didn't keep separate accumulators cleanly,
    // let's redo with explicit loops for clarity:
    let mut dot = 0.0f64;
    let norm_a_sq: f64 = 0.0;
    let norm_b_sq: f64 = 0.0;

    for (x, y) in a.iter().zip(b.iter()) {
        dot += x * y;
        norm_a_sq += x * x;
        norm_b_sq += y * y;
    }

    let norm_a = norm_a_sq.sqrt();
    let norm_b = norm_b_sq.sqrt();

    if norm_a == 0.0 || norm_b == 0.0 {
        return 0.0;
    }
    dot / (norm_a * norm_b)
}

fn main() {
    let a = vec![1.0, 2.0, 3.0];
    let b = vec![4.0, 5.0, 6.0];
    println!("Cosine similarity of {:?} and {:?}: {}", a, b, cosine_similarity(&a, &b));
}
