## 1. TypeScript

```typescript
import * as fs from 'fs';
import * as yaml from 'js-yaml'; // npm install js-yaml

interface Config {
  name: string;
  version: number;
  enabled: boolean;
}

/**
 * Parses and validates a YAML configuration file.
 *
 * @param filePath - Path to the .yaml / .yml file
 * @param requiredFields - Object mapping field names (keyof Config) to their expected types.
 *                         e.g. { name: string, version: number, enabled: boolean }
 * @returns An object containing the parsed config and a boolean `valid`.
 */
function parseAndValidateConfig(
  filePath: string,
  requiredFields: Record<string, unknown>
): { config: Config; valid: boolean } {
  let rawContent: string;
  try {
    rawContent = fs.readFileSync(filePath, 'utf-8');
  } catch (err) {
    return { config: null as Config; valid: false };
  }

  const data = yaml.parse(rawContent); // throws on parse error
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return { config: null as Config; valid: false };
  }

  const cfg: Partial<Config> = {};
  for (const [key, expectedType] of Object.entries(requiredFields) as [string, unknown][]) {
    if (cfg[key] === undefined) {
      // Field missing → invalid
      return { config: null as Config; valid: false };
    }
    const value = cfg[key];
    if (expectedType !== undefined && typeof value !== 'boolean' || expectedType === 'string' && typeof value !== 'string') {
      // Simple type check for common cases
      if (typeof expectedType === 'object' && expectedType !== null) {
        // e.g. number, boolean — handled above; otherwise skip deeper checks
      }
    }
  }

  const config: Config = {
    name: cfg.name as string,
    version: Number(cfg.version),
    enabled: Boolean(cfg.enabled),
  };

  return { config, valid: true };
}
```

> **Note:** `js-yaml` is a common YAML parser for Node. Install via `npm install js-yaml`.

