## 2. Python (3.9+)

```python
import yaml
from pathlib import Path
from typing import Any, Dict, Optional


class ConfigValidationError(Exception):
    """Raised when required fields are missing or have wrong types."""


def parse_and_validate_config(filepath: str, required_fields: Dict[str, type]) -> tuple[dict | None, bool]:
    """
    Parse a YAML file and validate that all keys in `required_fields`
    exist with the specified types.

    Parameters
    ----------
    filepath:
        Path to the .yaml or .yml configuration file.
    required_fields:
        Mapping of field name → expected Python type (e.g. {"name": str, "version": int}).

    Returns
    -------
        A tuple (config_dict, valid):
            config_dict: parsed dict if `valid` is True; None otherwise.
            valid: bool indicating whether all required fields are present and typed correctly.

    Raises
    ------
        ConfigValidationError
            If any required field is missing or its type does not match.
    """
    try:
        with open(filepath, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise ConfigValidationError(f"File not found: {filepath}")
    except yaml.YAMLError as e:
        raise ConfigValidationError(f"YAML parse error in {filepath}: {e}")

    if data is None or not isinstance(data, dict):
        raise ConfigValidationError(f"Configuration file must contain a YAML mapping; got {type(data).__name__}.")

    # Check required fields
    for field_name, expected_type in required_fields.items():
        if field_name not in data:
            raise ConfigValidationError(
                f"Missing required field '{field_name}' (expected type: {expected_type.__name__})"
            )
        value = data[field_name]
        if not isinstance(value, expected_type):
            raise ConfigValidationError(
                f"Field '{field_name}': expected type {expected_type.__name__}, "
                f"got {type(value).__name__} (value: {value!r})"
            )

    # Build the final config dict
    return data, True


# ---------- Example usage ----------
if __name__ == "__main__":
    try:
        cfg, valid = parse_and_validate_config(
            "config.yaml",
            {"name": str, "version": int, "enabled": bool}
        )
        print("Valid:", valid)
        if valid:
            print(f"Config: {cfg}")
    except ConfigValidationError as e:
        print("Validation failed:", e)
