## 3. Go (1.17+)

```go
package main

import (
	"fmt"
	"os"

	"gopkg.in/yaml.v3"
)

// Config represents the expected structure.
type Config struct {
	Name  string `yaml:"name"`
	Version int  `yaml:"version"`
	Enabled bool `yaml:"enabled"`
}

// RequiredFields maps field name → expected type (as a Go interface).
type RequiredFields map[string]interface{}

func parseAndValidateConfig(filepath string, requiredFields RequiredFields) (*Config, error) {
	var rawContent []byte
	if err := os.ReadFile(filepath); err != nil {
		return nil, fmt.Errorf("file not found: %w", err)
	}
	rawContent = string(rawContent)

	var data map[string]interface{}
	if err := yaml.Unmarshal([]byte(rawContent), &data); err != nil {
		return nil, fmt.Errorf("YAML parse error: %w", err)
	}

	// Check required fields
	for fieldName, expectedType := range requiredFields {
		if _, ok := data[fieldName]; !ok {
			return nil, fmt.Errorf("missing required field '%s' (expected type %T)", fieldName, expectedType)
		}
		foundValue, ok := data[fieldName].(expectedType)
		if !ok {
			return nil, fmt.Errorf(
				"field '%s': expected type %T, got %T (value: %v)",
				fieldName,
				expectedType,
				data[fieldName],
				foundValue != nil && fmt.Sprintf("%+v", foundValue),
			)
		}
	}

	return &Config{
		Name:  data["name"],
		Version: data["version"].(int),
		Enabled: data["enabled"].(bool),
	}, nil
}

func main() {
	cfg, err := parseAndValidateConfig("config.yaml", RequiredFields{
		"name":   "string",
		"version": int,
		"enabled": bool,
	})
	if err != nil {
		fmt.Printf("Validation failed: %v\n", err)
		return
	}
	fmt.Printf("Valid: true, Config: %+v\n", *cfg)
}
