// src/mergeConfig.ts

type MergeResult = Record<string, unknown>;

/**
 * Load environment variables into an object.
 */
function loadEnvVars(): Record<string, string | undefined> {
  const env: Record<string, string | undefined> = {};
  Object.keys(process.env).forEach(key => {
    if (key !== 'NODE_ENV') { // skip the NODE_ENV placeholder
      env[key] = process.env[key];
    }
  });
  return env;
}

/**
 * Load a JSON config file. Returns `undefined` on failure.
 */
function loadConfigFile(filePath: string): unknown {
  try {
    const raw = fs.readFileSync(filePath, 'utf-8');
    return JSON.parse(raw);
  } catch (e) {
    console.error(`⚠️  Could not parse ${filePath}:`, e);
    return undefined;
  }
}

/**
 * Merge configuration.
 *
 * @param cliFlags   Object of CLI-provided values (highest priority).
 * @param configFile Path to a JSON file containing the default config.
 * @returns A merged object with precedence: CLI > Config File > Environment Variables
 */
export function mergeConfig(
  cliFlags: Partial<MergeResult>,
  configFilePath: string,
): MergeResult {
  // Start with CLI flags (they win over everything)
  const result = { ...cliFlags };

  // Overlay values from the config file, but only if they aren't already set by CLI
  const cfg = loadConfigFile(configFilePath);
  if (cfg !== undefined && typeof cfg === 'object') {
    for (const key in cfg) {
      result[key] = cfg[key];
    }
  }

  // Finally, fill any remaining keys from environment variables
  const envVars = loadEnvVars();
  for (const key of Object.keys(envVars)) {
    if (!(key in result) || result[key] === undefined) {
      result[key] = envVars[key];
    }
  }

  return result;
}
```

