# src/merge_config.py

import json
import os


def load_env_vars() -> dict:
    """Return an object of environment variables (key → value)."""
    env = {}
    for key, val in os.environ.items():
        if key != "NODE_ENV":          # skip the placeholder used by some runtimes
            env[key] = val
    return env


def load_config_file(path: str) -> dict | None:
    """Parse a JSON config file. Returns None on failure."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return None
        return data
    except (json.JSONDecodeError, FileNotFoundError) as e:
        print(f"⚠️  Could not load config file {path}: {e}")
        return None


def merge_config(cli_flags: dict, config_file_path: str) -> dict:
    """
    Merge three sources with precedence:

      1. cli_flags (highest)
      2. config file (if it exists and is a JSON object)
      3. environment variables

    Parameters
    ----------
    cli_flags : dict
        Keys are configuration keys; values override everything else.
    config_file_path : str
        Path to a JSON file containing the default settings.

    Returns
    -------
        A merged dictionary where each key resolves as:
            cli_flag > config_value > env_var
    """
    # 1. Start with CLI flags (highest priority)
    result = {k: v for k, v in cli_flags.items() if v is not None}

    # 2. Overlay values from the config file (only if it exists and parses as a dict)
    cfg = load_config_file(config_file_path)
    if cfg is not None:
        result.update(cfg)

    # 3. Fill remaining keys with environment variables
    env_vars = load_env_vars()
    for key, value in env_vars.items():
        if key not in result or result.get(key) is None:
            result[key] = value

    return result


# ----------------------------------------------------------------------
if __name__ == "__main__":
    # Quick demo
    merged = merge_config(
        cli_flags={"port": 8080, "debug": True},
        config_file_path="/etc/app/config.json"
    )
