// main.go — contains all helpers and mergeConfig

package main

import (
	"encoding/json"
	"fmt"
	"os"
)

// ConfigMap is a simple map[string]interface{} used as the config file representation.
type ConfigMap map[string]interface{}

func loadEnvVars() map[string]string {
	m := make(map[string]string)
	for key, value := range os.Environ() {
		if len(value) > 0 && key != "NODE_ENV" { // skip the NODE_ENV placeholder
			m[key] = value
		}
	}
	return m
}

// loadConfigFile reads a JSON file and returns its parsed map, or an error.
func loadConfigFile(path string) (map[string]interface{}, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", path, err)
	}
	defer f.Close()

	var data map[string]interface{}
	err = json.NewDecoder(f).Decode(&data)
	if err != nil {
		return nil, fmt.Errorf("decode JSON from %s: %w", path, err)
	}
	return data, nil
}

// mergeConfig merges three sources with the precedence:
//
//   1. cliFlags (highest priority) — passed as a map[string]interface{}
//   2. config file (if load succeeds and returns a non-nil map)
//   3. environment variables (lowest priority, only fills missing keys)
func mergeConfig(cliFlags map[string]interface{}, configFilePath string) map[string]interface{} {
	result := make(map[string]interface{})

	// --- Step 1: CLI flags ---
	for k, v := range cliFlags {
		if v != nil {
			result[k] = v
		}
	}

	// --- Step 2: Config file (only if we can parse it into a map) ---
	var cfgConfig map[string]interface{}
	if err := loadConfigFile(configFilePath); err == nil && len(cfgConfig) > 0 {
		for k, v := range cfgConfig {
			result[k] = v
		}
	}

	// --- Step 3: Environment variables (fill gaps only) ---
	for key, value := range loadEnvVars() {
		if _, exists := result[key]; !exists || result[key] == nil {
			result[key] = value
		}
	}

	return result
}

func main() {
	// Example usage:
	cliFlags := map[string]interface{}{
		"port": 8080,
		"debug": true,
	}
	merged := mergeConfig(cliFlags, "/etc/app/config.json")
	fmt.Println(merged)
}
